<script setup lang="ts">
import { ref } from 'vue';
const props = defineProps<{ token?: string }>();
const kind = ref<'actor'|'scene'|'prop'|'layout'>('actor'); const tags = ref(''); const busy = ref(false); const message = ref('');
async function upload(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; busy.value = true; message.value = ''; try { const bytes = new Uint8Array(await file.arrayBuffer()); const digest = Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256', bytes))).map((v) => v.toString(16).padStart(2, '0')).join(''); let binary = ''; for (const byte of bytes) binary += String.fromCharCode(byte); const response = await fetch('/v1/assets/import', { method: 'POST', headers: { 'content-type': 'application/json', ...(props.token ? { authorization: `Bearer ${props.token}` } : {}) }, body: JSON.stringify({ logicalName: file.name, sha256: digest, mimeType: file.type || 'application/octet-stream', contentBase64: btoa(binary), actor: 'local-ui', assetKind: kind.value, tags: tags.value.split(',').map((v) => v.trim()).filter(Boolean) }) }); const payload = await response.json(); if (!response.ok) throw new Error(payload.code || 'IMPORT_FAILED'); message.value = `${kind.value}: ассет добавлен`; tags.value = ''; } catch (error) { message.value = String(error); } finally { busy.value = false; (event.target as HTMLInputElement).value = ''; } }
</script>
<template><details class="asset-workbench"><summary>Asset workbenches</summary><p class="uk-text-small uk-text-muted">Подготовьте типизированные ассеты для shot references.</p><div class="workbench-tabs"><button v-for="item in [['actor','Персонаж'],['scene','Локация'],['prop','Предмет'],['layout','Layout']]" :key="item[0]" type="button" :class="{active: kind === item[0]}" @click="kind = item[0] as any">{{ item[1] }}</button></div><input v-model="tags" class="uk-input uk-form-small" placeholder="Теги через запятую"><label class="workbench-upload"><input type="file" :disabled="busy" @change="upload"><span>{{ busy ? 'Загружаем…' : '＋ Добавить ассет' }}</span></label><p v-if="message" class="uk-text-small" :class="message.includes('добавлен') ? 'uk-text-success' : 'uk-text-danger'">{{ message }}</p></details></template>
<style scoped>.asset-workbench{margin-top:10px;padding:10px;border:1px solid var(--line,#303742);border-radius:10px}.workbench-tabs{display:flex;gap:4px;margin:8px 0}.workbench-tabs button{border:0;background:transparent;color:var(--muted,#97a1af);padding:5px 8px;border-radius:6px;cursor:pointer}.workbench-tabs button.active{background:var(--accent-deep,#367ed7);color:#fff}.workbench-upload{display:block;margin-top:8px;padding:8px;border:1px dashed var(--line,#303742);text-align:center;cursor:pointer}.workbench-upload input{display:none}</style>
